ESCALATION_FILE = os.path.join("data", "escalation_results.csv")
CONFLICT_FILE   = os.path.join("data", "conflict_results.csv")
CLEANED_FILE    = os.path.join("data", "cleaned_maternal_data.csv")
TREND_FILE      = os.path.join("data", "trend_results.csv")
DEMO_FILE       = os.path.join("data", "demo_conflict_cases.csv")

# ---------------------------------------------------------------------------
# BACKEND HELPERS  (unchanged logic)
# ---------------------------------------------------------------------------

def load_csv(filepath):
    """Load a CSV safely; show warning and return None if missing."""
    if not os.path.exists(filepath):
        st.warning(
            "Required data file not found: `" + filepath + "`\n\n"
            "Please run the pipeline: generate_data.py → clean_data.py → "
            "risk_detection.py → trend_analysis.py → "
            "conflict_detection.py → escalation_workflow.py"
        )
        return None
    try:
        return pd.read_csv(filepath)
    except Exception as e:
        st.error("Error reading `" + filepath + "`: " + str(e))
        return None


def safe_get(series, key, default=0):
    """Return count for a key from a value_counts Series."""
    try:
        return int(series.get(key, default))
    except Exception:
        return default

# ---------------------------------------------------------------------------
# UI COMPONENT HELPERS
# ---------------------------------------------------------------------------

def kpi(label, value, sub, css_class):
    """Render one KPI card."""
    return (
        f'<div class="kpi-card {css_class}">'
        f'  <div class="kpi-label">{label}</div>'
        f'  <div class="kpi-value">{value}</div>'
        f'  <div class="kpi-sub">{sub}</div>'
        f'</div>'
    )


def kpi_row(*cards):
    """Wrap cards in kpi-grid div."""
    inner = "".join(cards)
    st.markdown(f'<div class="kpi-grid">{inner}</div>', unsafe_allow_html=True)


def section(title):
    st.markdown(f'<div class="sec-title">{title}</div>', unsafe_allow_html=True)


def badge(text, kind="untrust"):
    cls = {
        "critical": "b-critical", "high": "b-high",
        "medium": "b-medium",     "low": "b-low",
        "untrust": "b-untrust",   "conflict": "b-conflict",
        "sensor": "b-sensor",     "insuff": "b-insuff",
        "ok": "b-ok",
    }.get(kind, "b-untrust")
    return f'<span class="badge {cls}">{text}</span>'


def priority_badge(p):
    kind = {"CRITICAL":"critical","HIGH":"high","MEDIUM":"medium",
            "LOW":"low","UNTRUSTED":"untrust"}.get(str(p).upper(), "untrust")
    return badge(p, kind)


def conflict_badge(s):
    s_up = str(s).upper()
    if "SENSOR-SYMPTOM" in s_up:   return badge(s, "conflict")
    if "SENSOR-ONLY"    in s_up:   return badge(s, "sensor")
    if "INSUFFICIENT"   in s_up:   return badge(s, "insuff")
    return badge(s, "ok")


def dashboard_header(title_line1, title_line2, subtitle):
    st.markdown(
        f'<div class="dash-header">'
        f'  <h1>{title_line1}<br>{title_line2}</h1>'
        f'  <p>{subtitle}</p>'
        f'  <span class="status-badge">&#9679; SYSTEM ACTIVE</span>'
        f'  <div class="disclaimer-bar">'
        f'    Educational prototype using simulated and anonymous data. '
        f'    Not a medical diagnostic system.'
        f'  </div>'
        f'</div>',
        unsafe_allow_html=True,
    )


def sub_header(title, subtitle=""):
    sub = f'<p style="margin:2px 0 0 0;font-size:0.8rem;color:#64748b;">{subtitle}</p>' if subtitle else ""
    st.markdown(
        f'<div style="margin:0.2rem 0 0.9rem 0;">'
        f'  <h2 style="margin:0;font-size:1.15rem;font-weight:700;color:#0f2744;">{title}</h2>'
        f'  {sub}'
        f'</div>',
        unsafe_allow_html=True,
    )

