def show_dashboard():
    dashboard_header(
        "Remote Maternal Health Monitoring",
        "and Escalation System",
        "Remote monitoring, symptom reconciliation and safe escalation for simulated maternal health observations.",
    )

    df = load_csv(ESCALATION_FILE)
    if df is None:
        return

    total = len(df)
    p    = df["priority"].value_counts()        if "priority"        in df.columns else pd.Series()
    ep   = df["escalation_path"].value_counts() if "escalation_path" in df.columns else pd.Series()
    sfwd = df["store_forward_status"].value_counts() if "store_forward_status" in df.columns else pd.Series()
    comm = df["communication_result"].value_counts()  if "communication_result"  in df.columns else pd.Series()
    cap  = df["capacity_status"].value_counts()       if "capacity_status"       in df.columns else pd.Series()

    # ── KPI CARDS ───────────────────────────────────────────────────────────
    section("LIVE MONITORING OVERVIEW")
    kpi_row(
        kpi("Total Observations", total,                      "Simulated monitoring records", "kpi-total"),
        kpi("CRITICAL",           safe_get(p, "CRITICAL"),    "Urgent clinician review",      "kpi-critical"),
        kpi("HIGH",               safe_get(p, "HIGH"),        "Clinician review",             "kpi-high"),
        kpi("MEDIUM",             safe_get(p, "MEDIUM"),      "Scheduled follow-up",          "kpi-medium"),
        kpi("LOW",                safe_get(p, "LOW"),         "Continue monitoring",          "kpi-low"),
        kpi("UNTRUSTED",          safe_get(p, "UNTRUSTED"),   "Safe fallback",                "kpi-untrust"),
    )

    st.markdown("<br>", unsafe_allow_html=True)

    # ── RISK OVERVIEW ───────────────────────────────────────────────────────
    section("RISK OVERVIEW")
    col_chart, col_summary = st.columns([3, 2])

    with col_chart:
        if "priority" in df.columns:
            risk_data = (
                df["priority"]
                .value_counts()
                .reindex(["LOW","MEDIUM","HIGH","CRITICAL","UNTRUSTED"], fill_value=0)
            )
            st.bar_chart(risk_data, color="#2563c7", height=220)

    with col_summary:
        crit = safe_get(p, "CRITICAL")
        high = safe_get(p, "HIGH")
        unt  = safe_get(p, "UNTRUSTED")
        low  = safe_get(p, "LOW")
        med  = safe_get(p, "MEDIUM")
        st.markdown(
            f'<div class="summary-panel">'
            f'  <h4>Risk Monitoring</h4>'
            f'  <div class="stat-row"><span class="stat-key">Total observations</span>'
            f'    <span class="stat-val">{total}</span></div>'
            f'  <div class="stat-row"><span class="stat-key">Critical</span>'
            f'    <span class="stat-val" style="color:#dc2626;">{crit}</span></div>'
            f'  <div class="stat-row"><span class="stat-key">High</span>'
            f'    <span class="stat-val" style="color:#ea580c;">{high}</span></div>'
            f'  <div class="stat-row"><span class="stat-key">Medium</span>'
            f'    <span class="stat-val" style="color:#d97706;">{med}</span></div>'
            f'  <div class="stat-row"><span class="stat-key">Low</span>'
            f'    <span class="stat-val" style="color:#16a34a;">{low}</span></div>'
            f'  <div class="stat-row"><span class="stat-key">Untrusted</span>'
            f'    <span class="stat-val" style="color:#6b7280;">{unt}</span></div>'
            f'  <p style="margin-top:0.8rem;font-size:0.76rem;color:#64748b;">'
            f'    Critical and high-risk observations are routed for clinician review, '
            f'    while uncertain observations use the safe fallback pathway.'
            f'  </p>'
            f'</div>',
            unsafe_allow_html=True,
        )

    st.markdown("<br>", unsafe_allow_html=True)

    # ── ESCALATION PATHWAYS ─────────────────────────────────────────────────
    section("ESCALATION PATHWAYS")
    col_esc, col_cap = st.columns([3, 2])

    with col_esc:
        if "escalation_path" in df.columns:
            esc_data = df["escalation_path"].value_counts()
