def show_patient_monitoring():
    sub_header(
        "Patient Monitoring",
        "Select an anonymous patient ID to view their full observation history and latest vitals.",
    )

    df = load_csv(ESCALATION_FILE)
    if df is None:
        return

    if "patient_id" not in df.columns:
        st.warning("Column 'patient_id' not found.")
        return

    patient_ids = sorted(df["patient_id"].dropna().unique().tolist())

    sel_col, _ = st.columns([2, 5])
    with sel_col:
        selected_id = st.selectbox("Select Patient ID:", options=patient_ids)

    patient_df = df[df["patient_id"] == selected_id]
    if patient_df.empty:
        st.warning("No records found for patient " + selected_id + ".")
        return

    if "observation_day" in patient_df.columns:
        row = patient_df.sort_values("observation_day", ascending=False).iloc[0]
        history_df = patient_df.sort_values("observation_day", ascending=True)
    else:
        row = patient_df.iloc[-1]
        history_df = patient_df

    priority     = str(row.get("priority", ""))
    final_action = str(row.get("final_action", "N/A"))
    prio_up      = priority.upper()

    # ── Patient header card ─────────────────────────────────────────────────
    prio_color = {"CRITICAL":"#dc2626","HIGH":"#ea580c","MEDIUM":"#d97706",
                  "LOW":"#16a34a","UNTRUSTED":"#6b7280"}.get(prio_up, "#64748b")
    st.markdown(
        f'<div style="background:#0f2744;border-radius:12px;padding:1rem 1.4rem;'
        f'margin-bottom:1rem;display:flex;justify-content:space-between;align-items:center;">'
        f'  <div>'
        f'    <div style="font-size:0.7rem;color:#a8c4e8;text-transform:uppercase;'
        f'         letter-spacing:0.08em;font-weight:600;">Selected Patient</div>'
        f'    <div style="font-size:1.5rem;font-weight:800;color:white;">{selected_id}</div>'
        f'    <div style="font-size:0.8rem;color:#a8c4e8;">'
        f'      Week {row.get("pregnancy_week","N/A")} &nbsp;|&nbsp; '
        f'      Day {row.get("observation_day","N/A")} &nbsp;|&nbsp; '
        f'      Quality: {row.get("data_quality","N/A")}'
        f'    </div>'
        f'  </div>'
        f'  <div style="text-align:right;">'
        f'    <div style="font-size:0.7rem;color:#a8c4e8;margin-bottom:4px;">Priority</div>'
        f'    <div style="font-size:1.3rem;font-weight:800;color:{prio_color};">{priority}</div>'
        f'  </div>'
        f'</div>',
        unsafe_allow_html=True,
    )

    # ── Tabs ────────────────────────────────────────────────────────────────
    tab_vitals, tab_symptoms, tab_workflow, tab_history = st.tabs([
        "Vital Signs", "Symptoms", "Risk & Escalation", "Observation History"
    ])

    # -- VITAL SIGNS --
    with tab_vitals:
        section("SENSOR READINGS — LATEST OBSERVATION")
        v1, v2, v3, v4, v5 = st.columns(5)

        def vital_box(col, label, val, unit):
            with col:
                st.markdown(
                    f'<div class="vital-box">'
                    f'  <div class="vital-label">{label}</div>'
                    f'  <div class="vital-value">{val}</div>'
                    f'  <div class="vital-unit">{unit}</div>'
                    f'</div>',
                    unsafe_allow_html=True,
                )

        vital_box(v1, "Systolic BP",  str(row.get("systolic_bp",  "N/A")), "mmHg")
        vital_box(v2, "Diastolic BP", str(row.get("diastolic_bp", "N/A")), "mmHg")
        vital_box(v3, "Heart Rate",   str(row.get("heart_rate",   "N/A")), "bpm")
        vital_box(v4, "Temperature",  str(row.get("temperature",  "N/A")), "°C")
        vital_box(v5, "SpO₂",         str(row.get("spo2",         "N/A")), "%")

        # BP trend chart
        section("SYSTOLIC BP TREND")
        bp_data = history_df[["observation_day", "systolic_bp"]].dropna() \
            if all(c in history_df.columns for c in ["observation_day","systolic_bp"]) \
            else pd.DataFrame()
        if not bp_data.empty:
            bp_idx = bp_data.set_index("observation_day")
            bp_idx.index = bp_idx.index.astype(str)
            st.line_chart(bp_idx, color="#dc2626", height=180)
            st.caption("Systolic BP (mmHg) across all observation days. Rising trends may indicate increasing risk.")
        else:
            st.info("No valid systolic BP readings available for chart.")

    # -- SYMPTOMS --
    with tab_symptoms:
        section("PATIENT-REPORTED SYMPTOMS")
        symptom_map = [
            ("headache",               "Headache"),
            ("blurred_vision",         "Blurred Vision"),
            ("bleeding",               "Bleeding"),
            ("abdominal_pain",         "Abdominal Pain"),
            ("swelling",               "Swelling"),
            ("reduced_fetal_movement", "Reduced Fetal Movement"),
        ]
        sym_html = '<div style="display:flex;flex-wrap:wrap;gap:10px;margin-top:0.4rem;">'
        any_yes = False
        for col_name, label in symptom_map:
            val = str(row.get(col_name, "No"))
            if val == "Yes":
                sym_html += f'<div><div class="vital-label">{label}</div><span class="sym-yes">⚠ {label}</span></div>'
                any_yes = True
            else:
                sym_html += f'<div><div class="vital-label">{label}</div><span class="sym-no">✓ No {label}</span></div>'
        sym_html += "</div>"
        st.markdown(sym_html, unsafe_allow_html=True)

        if any_yes:
            st.warning("One or more concerning symptoms reported. Review conflict status tab.")
        else:
            st.success("No concerning symptoms reported for this observation.")

    # -- RISK & ESCALATION --
    with tab_workflow:
        section("RISK ASSESSMENT")
        r1, r2, r3 = st.columns(3)
        with r1: st.markdown(f'<div class="info-card"><h4>Risk Level</h4>'
                             f'<p style="font-size:1.2rem;font-weight:800;color:#0f2744;">'
                             f'{row.get("risk_level","N/A")}</p></div>', unsafe_allow_html=True)
        with r2: st.markdown(f'<div class="info-card"><h4>Trend Status</h4>'
                             f'<p style="font-size:1.1rem;font-weight:700;color:#0f2744;">'
                             f'{row.get("trend_status","N/A")}</p></div>', unsafe_allow_html=True)
        with r3: st.markdown(f'<div class="info-card"><h4>Data Quality</h4>'
                             f'<p style="font-size:1.1rem;font-weight:700;color:#0f2744;">'
                             f'{row.get("data_quality","N/A")}</p></div>', unsafe_allow_html=True)

        st.markdown("<br>", unsafe_allow_html=True)
        section("CONFLICT & ESCALATION")
        e1, e2, e3, e4 = st.columns(4)
        conf_s = str(row.get("conflict_status", "N/A"))
        prio_s = str(row.get("priority", "N/A"))
        with e1:
            st.markdown("**Conflict Status**")
            st.markdown(conflict_badge(conf_s), unsafe_allow_html=True)
        with e2:
            st.markdown("**Priority**")
            st.markdown(priority_badge(prio_s), unsafe_allow_html=True)
        with e3:
            st.markdown("**Escalation Pathway**")
            st.write(str(row.get("escalation_path", "N/A")))
        with e4:
            st.markdown("**Schedule Status**")
            st.write(str(row.get("schedule_status", "N/A")))

        st.markdown("<br>", unsafe_allow_html=True)
        section("FINAL ESCALATION ACTION")
        action_cls = {
            "CRITICAL":"action-critical","HIGH":"action-high",
            "MEDIUM":"action-medium","LOW":"action-low","UNTRUSTED":"action-untrust",
        }.get(prio_up, "action-untrust")
        st.markdown(
            f'<div class="{action_cls}">'
            f'  <div style="font-size:0.72rem;font-weight:700;text-transform:uppercase;'
            f'       letter-spacing:0.06em;color:#64748b;margin-bottom:4px;">Recommended Action</div>'
            f'  <div style="font-size:1.05rem;font-weight:700;color:#1e293b;">{final_action}</div>'
            f'  <div style="font-size:0.75rem;color:#64748b;margin-top:4px;">'
            f'    Store-Forward: {row.get("store_forward_status","N/A")} &nbsp;|&nbsp; '
            f'    Communication: {row.get("communication_result","N/A")}'
            f'  </div>'
            f'</div>',
            unsafe_allow_html=True,
        )

    # -- HISTORY TABLE --
    with tab_history:
        section("ALL OBSERVATIONS — " + selected_id)
        history_cols = [
            "observation_day","pregnancy_week","systolic_bp","diastolic_bp",
            "heart_rate","data_quality","risk_level","trend_status",
            "conflict_status","priority","escalation_path","final_action",
        ]
        history_cols = [c for c in history_cols if c in df.columns]
        st.dataframe(history_df[history_cols], use_container_width=True, hide_index=True)


