def show_conflict_cases():
    sub_header(
        "Conflict Cases",
        "Phase 6 conflict detection checks whether sensor readings and patient-reported symptoms agree.",
    )

    df = load_csv(CONFLICT_FILE)
    if df is None:
        return

    cs = df["conflict_status"].value_counts() if "conflict_status" in df.columns else pd.Series()

    # ── Summary KPIs ─────────────────────────────────────────────────────
    section("CONFLICT SUMMARY")
    kpi_row(
        kpi("Total Cases",            len(df),                                   "All processed observations", "kpi-total"),
        kpi("Sensor-Symptom Conflict",safe_get(cs,"SENSOR-SYMPTOM CONFLICT"),   "Sensor vs symptoms mismatch","kpi-critical"),
        kpi("Sensor-Only Concern",    safe_get(cs,"SENSOR-ONLY CONCERN"),       "Abnormal sensor, no symptoms","kpi-high"),
        kpi("Symptom-Only Concern",   safe_get(cs,"SYMPTOM-ONLY CONCERN"),      "Symptoms, normal sensor",    "kpi-medium"),
        kpi("Insufficient Data",      safe_get(cs,"INSUFFICIENT DATA"),         "Data quality too poor",      "kpi-untrust"),
    )

    st.markdown("<br>", unsafe_allow_html=True)

    # ── Conflict type guide ──────────────────────────────────────────────
    section("CONFLICT TYPE GUIDE")
    g1, g2, g3, g4 = st.columns(4)
    guides = [
        ("b-conflict","SENSOR-SYMPTOM CONFLICT",
         "Sensor shows LOW/MEDIUM risk but patient reports concerning symptoms. Symptoms take priority over sensor."),
        ("b-sensor",  "SENSOR-ONLY CONCERN",
         "Sensor shows HIGH/CRITICAL risk but no symptoms reported. Sensor reading is NOT dismissed."),
        ("b-insuff",  "INSUFFICIENT DATA",
         "Data quality is too poor to reliably assess. Routes to SAFE FALLBACK — never classified as LOW."),
        ("b-ok",      "NO CONFLICT",
         "Sensor and symptoms both agree. Routine monitoring can continue as normal."),
    ]
    for col, (cls, title, desc) in zip([g1,g2,g3,g4], guides):
        with col:
            st.markdown(
                f'<div class="info-card">'
                f'  <span class="badge {cls}" style="margin-bottom:8px;display:inline-block;">{title}</span>'
                f'  <p>{desc}</p>'
                f'</div>',
                unsafe_allow_html=True,
            )

    st.markdown("<br>", unsafe_allow_html=True)

    # ── Conflict cases table ──────────────────────────────────────────────
    section("FLAGGED CASES TABLE")
    conflict_display_cols = [
        "patient_id","risk_level","concerning_symptoms",
        "trend_status","conflict_status","conflict_reason","final_workflow_action",
    ]
    conflict_display_cols = [c for c in conflict_display_cols if c in df.columns]

    if "conflict_status" in df.columns:
        conflict_only = df[df["conflict_status"] != "NO CONFLICT"]
    else:
        conflict_only = df

    no_conflict_count = safe_get(cs, "NO CONFLICT")
    st.caption(
        "Showing **" + str(len(conflict_only)) + "** flagged records — "
        "excludes " + str(no_conflict_count) + " routine NO CONFLICT records."
    )
    st.dataframe(conflict_only[conflict_display_cols], use_container_width=True, hide_index=True)

    st.markdown("<br>", unsafe_allow_html=True)

    # ── Demo cases ───────────────────────────────────────────────────────
    section("SIMULATED DEMONSTRATION CASES")
    st.error(
        "SIMULATED DEMONSTRATION CASES — NOT REAL PATIENTS\n\n"
        "DEMO001–DEMO006 are hand-crafted to cover every conflict detection and "
        "escalation scenario. They are entirely fictional."
    )

    demo_df = load_csv(DEMO_FILE)
    if demo_df is None:
        return

    demo_meta = {
        "DEMO001": ("SENSOR-SYMPTOM CONFLICT", "b-conflict", "LOW",   "Headache + Blurred Vision", "CLINICIAN_REVIEW"),
        "DEMO002": ("SENSOR-ONLY CONCERN",      "b-sensor",  "HIGH",  "None reported",             "CLINICIAN_REVIEW"),
        "DEMO003": ("NO CONFLICT (both high)",  "b-conflict","HIGH",  "Headache + Blurred Vision", "URGENT_CLINICIAN_REVIEW"),
        "DEMO004": ("INSUFFICIENT DATA",        "b-insuff",  "UNCERTAIN","None",                   "SAFE_FALLBACK"),
        "DEMO005": ("NO CONFLICT",              "b-ok",      "LOW",   "None",                      "CONTINUE_MONITORING"),
        "DEMO006": ("NO CONFLICT (offline)",    "b-sensor",  "HIGH",  "Headache + Blurred Vision", "URGENT_CLINICIAN_REVIEW"),
    }
    demo_explanations = {
        "DEMO001": "LOW sensor risk + headache + blurred vision → symptoms take priority → CLINICIAN REVIEW.",
        "DEMO002": "HIGH sensor risk + no symptoms → sensor NOT dismissed → CLINICIAN REVIEW.",
        "DEMO003": "HIGH sensor risk + headache + blurred vision → both concerning → URGENT CLINICIAN REVIEW.",
        "DEMO004": "UNCERTAIN risk + incomplete data + offline → SAFE FALLBACK. Never classified as LOW.",
        "DEMO005": "LOW sensor risk + no symptoms + good quality → NO CONFLICT → CONTINUE MONITORING.",
        "DEMO006": "HIGH sensor risk + symptoms + OFFLINE → CRITICAL + store-and-forward → URGENT REVIEW.",
    }

    for _, row in demo_df.iterrows():
        pid      = str(row.get("patient_id", ""))
        risk     = str(row.get("risk_level",  "N/A"))
        internet = str(row.get("internet_status", "N/A"))
        comm     = str(row.get("communication_status", "N/A"))
        conf_label, conf_cls, _, syms, action = demo_meta.get(
            pid, ("UNKNOWN","b-untrust","N/A","N/A","N/A")
        )
        explanation = demo_explanations.get(pid, "")

        with st.expander(pid + "  —  " + conf_label + "  |  Internet: " + internet):
            st.markdown(
                f'<div style="margin-bottom:0.6rem;">'
                f'  <div class="demo-id">{pid}</div>'
                f'  <span class="badge {conf_cls}">{conf_label}</span>'
                f'</div>'
                f'<div class="demo-row">'
                f'  <div class="demo-field">Sensor Risk: <span>{risk}</span></div>'
                f'  <div class="demo-field">Symptoms: <span>{syms}</span></div>'
                f'  <div class="demo-field">Internet: <span>{internet}</span></div>'
                f'  <div class="demo-field">Communication: <span>{comm}</span></div>'
                f'  <div class="demo-field">Action: <span>{action}</span></div>'
                f'</div>',
                unsafe_allow_html=True,
            )
            st.info(explanation)

            dc1, dc2 = st.columns(2)
            with dc1:
                st.markdown("**Sensor Readings**")
                for field, label in [
                    ("systolic_bp","Systolic BP"),("diastolic_bp","Diastolic BP"),
                    ("heart_rate","Heart Rate"),("temperature","Temperature"),("spo2","SpO₂"),
                    ("data_quality","Data Quality"),
                ]:
                    st.write(f"{label}: {row.get(field,'N/A')}")
            with dc2:
                st.markdown("**Symptoms**")
                for col_name, label in [
                    ("headache","Headache"),("blurred_vision","Blurred Vision"),
                    ("bleeding","Bleeding"),("abdominal_pain","Abdominal Pain"),
                    ("swelling","Swelling"),("reduced_fetal_movement","Reduced Fetal Movement"),
                ]:
                    val = str(row.get(col_name,"No"))
                    if val == "Yes":
                        st.markdown(f'<span class="sym-yes">⚠ {label}</span>', unsafe_allow_html=True)
                    else:
                        st.markdown(f'<span class="sym-no">✓ No {label}</span>', unsafe_allow_html=True)
                    st.markdown("&nbsp;", unsafe_allow_html=True)


