def show_escalation_queue():
    sub_header(
        "Escalation Queue",
        "All observations sorted by priority. Clinician capacity: 10 HIGH/CRITICAL cases per review cycle.",
    )

    df = load_csv(ESCALATION_FILE)
    if df is None:
        return

    p   = df["priority"].value_counts()        if "priority"        in df.columns else pd.Series()
    cap = df["capacity_status"].value_counts()  if "capacity_status" in df.columns else pd.Series()

    # ── Priority KPIs ─────────────────────────────────────────────────────
    section("PRIORITY OVERVIEW")
    kpi_row(
        kpi("CRITICAL",  safe_get(p,"CRITICAL"),  "Urgent review required", "kpi-critical"),
        kpi("HIGH",      safe_get(p,"HIGH"),      "Clinician review",       "kpi-high"),
        kpi("MEDIUM",    safe_get(p,"MEDIUM"),    "Scheduled follow-up",    "kpi-medium"),
        kpi("LOW",       safe_get(p,"LOW"),       "Continue monitoring",    "kpi-low"),
        kpi("UNTRUSTED", safe_get(p,"UNTRUSTED"), "Safe fallback",          "kpi-untrust"),
    )

    st.markdown("<br>", unsafe_allow_html=True)

    # ── Clinician capacity ───────────────────────────────────────────────
    section("CLINICIAN CAPACITY")
    within = safe_get(cap,"WITHIN_CAPACITY")
    queued = safe_get(cap,"QUEUED")
    pct    = min(int((within / 10) * 100), 100)

    cc1, cc2, cc3, cc4 = st.columns([1,1,1,3])
    with cc1:
        st.markdown(
            '<div class="kpi-card kpi-blue"><div class="kpi-label">Capacity Limit</div>'
            '<div class="kpi-value">10</div>'
            '<div class="kpi-sub">Cases per cycle</div></div>',
            unsafe_allow_html=True,
        )
    with cc2:
        st.markdown(
            f'<div class="kpi-card kpi-green"><div class="kpi-label">Within Capacity</div>'
            f'<div class="kpi-value">{within}</div>'
            f'<div class="kpi-sub">Immediate review</div></div>',
            unsafe_allow_html=True,
        )
    with cc3:
        st.markdown(
            f'<div class="kpi-card kpi-orange"><div class="kpi-label">Queued</div>'
            f'<div class="kpi-value">{queued}</div>'
            f'<div class="kpi-sub">Next available slot</div></div>',
            unsafe_allow_html=True,
        )
    with cc4:
        st.markdown(
            f'<div style="padding:0.9rem 1rem;background:#f8faff;border:1px solid #dbe8f8;'
            f'border-radius:12px;height:100%;">'
            f'  <div style="font-size:0.8rem;font-weight:600;color:#0f2744;margin-bottom:6px;">'
            f'    Immediate Capacity Utilisation: {within}/10 slots</div>'
            f'  <div class="cap-outer"><div class="cap-inner" style="width:{pct}%;"></div></div>'
            f'  <div style="font-size:0.74rem;color:#64748b;margin-top:6px;">'
            f'    First 10 eligible HIGH/CRITICAL cases = immediate review. '
            f'    Remaining {queued} cases queued for next available slot. '
            f'    Cases are NEVER discarded — priority is preserved in the queue.</div>'
            f'</div>',
            unsafe_allow_html=True,
        )

    st.markdown("<br>", unsafe_allow_html=True)

    # ── Priority tabs ────────────────────────────────────────────────────
    if "priority" in df.columns:
        critical_df = df[df["priority"] == "CRITICAL"].copy()
        high_df     = df[df["priority"] == "HIGH"].copy()

        high_crit_cols = [c for c in [
            "patient_id","observation_day","risk_level","conflict_status",
            "escalation_path","schedule_status","capacity_status",
            "communication_result","store_forward_status","final_action",
        ] if c in df.columns]

        tab_crit, tab_high = st.tabs([
            "🔴 CRITICAL  (" + str(len(critical_df)) + " cases)",
            "🟠 HIGH  ("     + str(len(high_df))     + " cases)",
        ])
        with tab_crit:
            if not critical_df.empty:
                st.dataframe(critical_df[high_crit_cols], use_container_width=True, hide_index=True)
            else:
                st.info("No CRITICAL priority cases.")
        with tab_high:
            if not high_df.empty:
                st.dataframe(high_df[high_crit_cols], use_container_width=True, hide_index=True)
            else:
                st.info("No HIGH priority cases.")

    st.markdown("<br>", unsafe_allow_html=True)

    # ── Full queue with filter ────────────────────────────────────────────
    section("FULL ESCALATION QUEUE")

    priority_order = {"CRITICAL":0,"HIGH":1,"UNTRUSTED":2,"MEDIUM":3,"LOW":4}
    sorted_df = df.copy()
    if "priority" in sorted_df.columns:
        sorted_df["_sk"] = sorted_df["priority"].map(lambda x: priority_order.get(str(x),99))
        sorted_df = sorted_df.sort_values("_sk").drop(columns=["_sk"])

    display_cols = [c for c in [
        "patient_id","priority","escalation_path","schedule_status",
        "capacity_status","communication_result","store_forward_status","final_action",
    ] if c in sorted_df.columns]

    fc, _ = st.columns([3,4])
    with fc:
        sel_p = st.multiselect(
            "Filter by priority:",
            options=["CRITICAL","HIGH","UNTRUSTED","MEDIUM","LOW"],
            default=["CRITICAL","HIGH","UNTRUSTED"],
        )

    filtered = sorted_df[sorted_df["priority"].isin(sel_p)] \
        if sel_p and "priority" in sorted_df.columns else sorted_df

    st.caption(
        "Showing **" + str(len(filtered)) + "** of **" + str(len(df)) +
        "** records, sorted most urgent first."
    )
    st.dataframe(filtered[display_cols], use_container_width=True, hide_index=True)


