    with d3:
        # Live from trend CSV
        trend_df = load_csv(TREND_FILE)
        if trend_df is not None and "overall_trend" in trend_df.columns:
            tv = trend_df["overall_trend"].value_counts()
            inc  = int(tv.get("Consistently Increasing", 0))
            dec  = int(tv.get("Consistently Decreasing", 0))
            stab = int(tv.get("Stable/Variable", 0))
        else:
            inc = dec = stab = 0
        st.markdown(
            f'<div class="summary-panel"><h4>BP Trends (100 patients)</h4>'
            f'<div class="stat-row"><span class="stat-key">Increasing</span><span class="stat-val" style="color:#dc2626;">{inc}</span></div>'
            f'<div class="stat-row"><span class="stat-key">Decreasing</span><span class="stat-val" style="color:#16a34a;">{dec}</span></div>'
            f'<div class="stat-row"><span class="stat-key">Stable/Variable</span><span class="stat-val">{stab}</span></div>'
            f'</div>',
            unsafe_allow_html=True,
        )

    with d4:
        # Live from escalation CSV
        esc_df = load_csv(ESCALATION_FILE)
        if esc_df is not None and "communication_result" in esc_df.columns:
            cv = esc_df["communication_result"].value_counts()
            comp  = int(cv.get("Clinician contact completed.", 0))
            pend  = int(cv.get("Clinician contact pending.", 0))
            fail  = int(cv.get("First communication attempt failed.", 0))
        else:
            comp = pend = fail = 0
        sf_df = esc_df if esc_df is not None else pd.DataFrame()
        stored = int(sf_df["store_forward_status"].value_counts().get("STORED", 0)) \
            if esc_df is not None and "store_forward_status" in sf_df.columns else 0
        st.markdown(
            f'<div class="summary-panel"><h4>Communication</h4>'
            f'<div class="stat-row"><span class="stat-key">Completed</span><span class="stat-val" style="color:#16a34a;">{comp}</span></div>'
            f'<div class="stat-row"><span class="stat-key">Pending</span><span class="stat-val">{pend}</span></div>'
            f'<div class="stat-row"><span class="stat-key">Failed</span><span class="stat-val" style="color:#ea580c;">{fail}</span></div>'
            f'<div class="stat-row"><span class="stat-key">Stored (offline)</span><span class="stat-val" style="color:#6b7280;">{stored}</span></div>'
            f'</div>',
            unsafe_allow_html=True,
        )

    st.markdown("<br>", unsafe_allow_html=True)

    # ── Phase result tabs ─────────────────────────────────────────────────
    section("PHASE-BY-PHASE LIVE RESULTS")
    t4, t5, t6, t7 = st.tabs([
        "Phase 4 – Risk","Phase 5 – Trend","Phase 6 – Conflict","Phase 7 – Escalation"
    ])

    with t4:
        risk_df = load_csv(os.path.join("data","baseline_risk_results.csv"))
        if risk_df is not None and "risk_level" in risk_df.columns:
            cl, cr = st.columns(2)
            with cl:
                rc = risk_df["risk_level"].value_counts().reset_index()
                rc.columns = ["Risk Level","Count"]
                st.dataframe(rc, use_container_width=True, hide_index=True)
            with cr:
                st.bar_chart(
                    risk_df["risk_level"].value_counts()
                    .reindex(["CRITICAL","HIGH","MEDIUM","LOW","UNCERTAIN"],fill_value=0),
                    color="#2563c7", height=200,
                )

    with t5:
        if trend_df is not None and "overall_trend" in trend_df.columns:
            cl, cr = st.columns(2)
            with cl:
                tc = trend_df["overall_trend"].value_counts().reset_index()
                tc.columns = ["Trend","Count"]
                st.dataframe(tc, use_container_width=True, hide_index=True)
            with cr:
                st.bar_chart(trend_df["overall_trend"].value_counts(), color="#16a34a", height=200)

    with t6:
        cf_df = load_csv(CONFLICT_FILE)
        if cf_df is not None and "conflict_status" in cf_df.columns:
            cl, cr = st.columns(2)
            with cl:
                cc = cf_df["conflict_status"].value_counts().reset_index()
                cc.columns = ["Conflict Status","Count"]
                st.dataframe(cc, use_container_width=True, hide_index=True)
            with cr:
                st.bar_chart(cf_df["conflict_status"].value_counts(), color="#ea580c", height=200)

    with t7:
        if esc_df is not None and "escalation_path" in esc_df.columns:
            cl, cr = st.columns(2)
            with cl:
                ec = esc_df["escalation_path"].value_counts().reset_index()
                ec.columns = ["Escalation Path","Count"]
                st.dataframe(ec, use_container_width=True, hide_index=True)
            with cr:
                st.bar_chart(esc_df["escalation_path"].value_counts(), color="#8b5cf6", height=200)

    st.markdown("<br>", unsafe_allow_html=True)

    # ── Module table ──────────────────────────────────────────────────────
    section("PROJECT MODULES")
    module_data = {
        "Phase": ["2","3","4","5","6","7","8"],
        "Module": [
            "generate_data.py","clean_data.py","risk_detection.py",
            "trend_analysis.py","conflict_detection.py",
            "escalation_workflow.py","app.py",
        ],
        "Purpose": [
            "Generates 994 simulated anonymous patient records",
            "Flags records as Good / Incomplete / Invalid",
            "Assigns LOW / MEDIUM / HIGH / UNCERTAIN risk level",
            "Detects systolic BP trends across patient observations",
            "Detects sensor-symptom mismatches",
            "Routes cases to the correct escalation pathway",
            "Streamlit monitoring dashboard (this file)",
        ],
    }
    st.dataframe(pd.DataFrame(module_data), use_container_width=True, hide_index=True)

    st.markdown("<br>", unsafe_allow_html=True)

    # ── Privacy & disclaimer ──────────────────────────────────────────────
    st.markdown(
        '<div class="privacy-card">'
        '  <h4>🔒 PRIVACY BY DESIGN</h4>'
        '  <div class="privacy-item">✓ &nbsp; Anonymous patient IDs — P001–P100 and DEMO001–DEMO006</div>'
        '  <div class="privacy-item">✓ &nbsp; All 994 records are entirely simulated — no real patients</div>'
        '  <div class="privacy-item">✓ &nbsp; No names, phone numbers, addresses, or contact details</div>'
        '  <div class="privacy-item">✓ &nbsp; This system is NOT a medical diagnostic tool</div>'
        '  <div class="privacy-item">✓ &nbsp; Do NOT use for real clinical decisions</div>'
        '</div>',
        unsafe_allow_html=True,
    )


